//! Snapshot tests for formatter output.
//!
//! Use these when input != expected output: messy/unformatted Ruby
//! files, or config-driven formatting where the same input produces
//! different output. Each `.rb` file under `tests/fixtures/format_messy/`
//! is formatted and compared against a committed insta snapshot.
//!
//! Run `cargo insta review` to accept new/changed snapshots.

use std::fs;
use std::path::Path;

/// Checks the fixture `tests/fixtures/format_messy/<name>.rb` against its
/// snapshot; the tests that call it are generated by `build.rs`, one per
/// file.
fn check_messy_fixture(name: &str) {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/format_messy")
        .join(format!("{name}.rb"));
    let input = fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    let snapshot_name = name.replace('/', "__");

    let output = tuxedo::format(&input).unwrap_or_else(|e| panic!("{}: {e}", path.display()));

    insta::assert_snapshot!(snapshot_name, output);

    let reformatted = tuxedo::format(&output).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    assert_eq!(
        output,
        reformatted,
        "formatting is not idempotent for fixture: {}",
        path.display()
    );
}

include!(concat!(env!("OUT_DIR"), "/messy_fixtures.rs"));
